# Generated from shapes/agent-memory.shapes.ttl sha256:93542548160a80c237189176c87709403a00e26b127026badf21a4741e8cff23
# by scripts/memory_schema_proposal.py (aegis-gshu.12). Do not hand-edit.
@prefix aegis: <http://aegis.gastown.local/ontology/> .
@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .
@prefix prov:  <http://www.w3.org/ns/prov#> .

aegis:MemoryDecisionBodyShape a sh:NodeShape ;
    sh:property [
        sh:path aegis:chose ; sh:minCount 1 ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 1 ; sh:name "chose" ;
        sh:description "What was chosen, in one sentence." ;
        sh:message "Not recorded: a decision needs what was chosen (--chose)." ] ;
    sh:property [
        sh:path aegis:decidedBy ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 2 ; sh:name "by" ;
        sh:description "Who ruled: a Person or agent entity (IRI or local name)." ;
        sh:message "Not recorded: a decision needs who ruled (--by), as an existing person or agent." ] ;
    sh:property [
        sh:path aegis:about ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 3 ; sh:name "about" ;
        sh:description "The entity the decision is about: host, repo, service, role, agent or person (IRI or local name)." ;
        sh:message "Not recorded: a decision needs what it is about (--about), as an existing entity." ] ;
    sh:property [
        sh:path aegis:topic ; sh:minCount 1 ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 4 ; sh:name "topic" ;
        sh:description "The registered memory topic the decision answers (cy topic add registers one)." ;
        sh:message "Not recorded: a decision needs a registered topic (--topic)." ] ;
    sh:property [
        sh:path aegis:over ; sh:datatype xsd:string ;
        sh:order 5 ; sh:name "over" ;
        sh:description "An alternative that was not chosen; repeat for each." ;
        sh:message "Not recorded: --over is plain text, one alternative per flag." ] ;
    sh:property [
        sh:path aegis:rationale ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 6 ; sh:name "rationale" ;
        sh:description "Why, in one or two sentences." ;
        sh:message "Not recorded: give one --rationale." ] ;
    sh:property [
        sh:path aegis:decidedIn ; sh:maxCount 1 ; sh:nodeKind sh:IRI ;
        sh:order 7 ; sh:name "decidedIn" ;
        sh:description "The board item or session the decision was made in (IRI or local name)." ;
        sh:message "Not recorded: --decided-in names one board item or session." ] ;
    sh:property [
        sh:path aegis:verbatim ; sh:maxCount 1 ; sh:datatype xsd:string ;
        sh:order 8 ; sh:name "verbatim" ;
        sh:description "The ruling in the decider's own words." ;
        sh:message "Not recorded: give one --verbatim quote." ] .


# Scoped: only memory records (subjects of aegis:naturalKey) typed aegis:Decision are
# checked. The live aegis:Decision nodes written before camayoc have no naturalKey
# and stay untouched until someone rewrites them as memory records.
aegis:MemoryDecisionShape a sh:NodeShape ;
    sh:targetSubjectsOf aegis:naturalKey ;
    sh:or ( [ sh:not [ sh:class aegis:Decision ] ] [ sh:node aegis:MemoryDecisionBodyShape ] ) ;
    sh:message "A memory Decision needs --chose, --decided-by, --about and --topic, each exactly once. Run the cy create tool with --help for each field." .
